"use client";

import { addClassNamesToElement } from "@lexical/utils";
import type {
  DOMConversionMap,
  DOMConversionOutput,
  DOMExportOutput,
  EditorConfig,
  LexicalNode,
  LexicalUpdateJSON,
  NodeKey,
  SerializedLexicalNode,
  Spread,
} from "lexical";
import { DecoratorNode } from "lexical";
import type { JSX } from "react";
import { MathComponent } from "../../../plugins/math/component";

export type SerializedMathNode = Spread<
  {
    equation: string;
    inline: boolean;
  },
  SerializedLexicalNode
>;

export interface MathPayload {
  equation: string;
  inline?: boolean;
  key?: NodeKey;
}

const convertMathElement = (domNode: Node): DOMConversionOutput | null => {
  if (!(domNode instanceof HTMLElement)) {
    return null;
  }

  const equation = domNode.getAttribute("data-equation");
  if (equation === null) {
    return null;
  }

  const inline = domNode.getAttribute("data-inline") !== "false";

  return {
    node: $createMathNode({
      equation,
      inline,
    }),
  };
};

export class MathNode extends DecoratorNode<JSX.Element> {
  __equation: string;
  __inline: boolean;

  constructor(equation: string, inline = true, key?: NodeKey) {
    super(key);
    this.__equation = equation;
    this.__inline = inline;
  }

  static getType(): string {
    return "math";
  }

  static clone(node: MathNode): MathNode {
    return new MathNode(node.__equation, node.__inline, node.__key);
  }

  static importDOM(): DOMConversionMap | null {
    return {
      div: (domNode: Node) => {
        if (
          domNode instanceof HTMLElement &&
          domNode.hasAttribute("data-equation")
        ) {
          return {
            conversion: convertMathElement,
            priority: 2,
          };
        }
        return null;
      },
      span: (domNode: Node) => {
        if (
          domNode instanceof HTMLElement &&
          domNode.hasAttribute("data-equation")
        ) {
          return {
            conversion: convertMathElement,
            priority: 2,
          };
        }
        return null;
      },
    };
  }

  static importJSON(serializedNode: SerializedMathNode): MathNode {
    return $createMathNode({
      equation: serializedNode.equation,
      inline: serializedNode.inline,
    }).updateFromJSON(serializedNode);
  }

  updateFromJSON(serializedNode: LexicalUpdateJSON<SerializedMathNode>): this {
    return super
      .updateFromJSON(serializedNode)
      .setEquation(serializedNode.equation)
      .setInline(serializedNode.inline);
  }

  exportDOM(): DOMExportOutput {
    const element = document.createElement(this.__inline ? "span" : "div");
    element.setAttribute("data-lexical-math", "true");
    element.setAttribute("data-equation", this.__equation);
    element.setAttribute("data-inline", this.__inline ? "true" : "false");
    element.textContent = this.__equation;
    return { element };
  }

  exportJSON(): SerializedMathNode {
    return {
      ...super.exportJSON(),
      equation: this.__equation,
      inline: this.__inline,
      type: "math",
      version: 1,
    };
  }

  createDOM(config: EditorConfig): HTMLElement {
    const element = document.createElement(this.__inline ? "span" : "div");

    if (typeof config.theme.math === "string") {
      addClassNamesToElement(element, config.theme.math);
    }

    if (this.__inline) {
      element.className = "inline-block cursor-pointer select-none";
    } else {
      element.className = "block my-2 cursor-pointer select-none text-center";
    }

    return element;
  }

  updateDOM(prevNode: MathNode): boolean {
    return this.__inline !== prevNode.__inline;
  }

  getTextContent(): string {
    return this.__equation;
  }

  decorate(): JSX.Element {
    return (
      <MathComponent
        equation={this.__equation}
        inline={this.__inline}
        nodeKey={this.getKey()}
      />
    );
  }

  isInline(): boolean {
    return this.__inline;
  }

  getEquation(): string {
    return this.getLatest().__equation;
  }

  setEquation(equation: string): this {
    const writable = this.getWritable();
    writable.__equation = equation;
    return writable;
  }

  getInline(): boolean {
    return this.getLatest().__inline;
  }

  setInline(inline: boolean): this {
    const writable = this.getWritable();
    writable.__inline = inline;
    return writable;
  }
}

export function $createMathNode({
  equation,
  inline = true,
  key,
}: MathPayload): MathNode {
  return new MathNode(equation, inline, key);
}

export function $isMathNode(
  node: LexicalNode | null | undefined
): node is MathNode {
  return node instanceof MathNode;
}

import type {
  MultilineElementTransformer,
  TextMatchTransformer,
} from "@lexical/markdown";
import { $createMathNode, $isMathNode, MathNode } from "./node";

export const MATH_INLINE_MARKDOWN_TRANSFORMER: TextMatchTransformer = {
  dependencies: [MathNode],
  export: (node) => {
    if (!($isMathNode(node) && node.getInline())) {
      return null;
    }
    return `$${node.getEquation()}$`;
  },
  importRegExp: /\$([^$]+)\$/,
  regExp: /\$([^$]+)\$/,
  replace: (node, match) => {
    const [, equation] = match;
    if (!equation) {
      return;
    }
    node.replace($createMathNode({ equation, inline: true }));
  },
  trigger: "$",
  type: "text-match",
};

export const MATH_BLOCK_MARKDOWN_TRANSFORMER: MultilineElementTransformer = {
  dependencies: [MathNode],
  export: (node) => {
    if (!$isMathNode(node) || node.getInline()) {
      return null;
    }
    return `$$\n${node.getEquation()}\n$$`;
  },
  handleImportAfterStartMatch: ({ lines, rootNode, startLineIndex }) => {
    const startLine = lines[startLineIndex];
    if (!startLine) {
      return null;
    }

    if (
      startLine.startsWith("$$") &&
      startLine.endsWith("$$") &&
      startLine.length > 4
    ) {
      const equation = startLine.slice(2, -2).trim();
      rootNode.append($createMathNode({ equation, inline: false }));
      return [true, startLineIndex];
    }

    if (startLine.trim() !== "$$") {
      return null;
    }

    const equationLines: string[] = [];
    let lineIndex = startLineIndex + 1;

    while (lineIndex < lines.length) {
      const line = lines[lineIndex] ?? "";
      if (line.trim() === "$$") {
        break;
      }
      equationLines.push(line);
      lineIndex += 1;
    }

    const equation = equationLines.join("\n").trim();
    rootNode.append($createMathNode({ equation, inline: false }));
    return [true, lineIndex];
  },
  regExpEnd: {
    optional: true,
    regExp: /^\$\$\s*$/,
  },
  regExpStart: /^\$\$\s*$/,
  replace: () => false,
  type: "multiline-element",
};

import { createCommand, type LexicalCommand } from "lexical";
import type { MathPayload } from "../../core/nodes/math/node";

export const INSERT_MATH_COMMAND: LexicalCommand<MathPayload> = createCommand(
  "INSERT_MATH_COMMAND"
);

"use client";

// Bundled with the feature so `editor-math` installs render correctly
// without the consumer importing the stylesheet manually. Bundlers dedupe
// it if the app also imports it from its own CSS.
import "katex/dist/katex.min.css";
import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { useLexicalEditable } from "@lexical/react/useLexicalEditable";
import { useLexicalNodeSelection } from "@lexical/react/useLexicalNodeSelection";
import { mergeRegister } from "@lexical/utils";
import katex from "katex";
import {
  $getNodeByKey,
  $getSelection,
  $isNodeSelection,
  CLICK_COMMAND,
  COMMAND_PRIORITY_LOW,
  KEY_BACKSPACE_COMMAND,
  KEY_DELETE_COMMAND,
  type NodeKey,
} from "lexical";
import { CheckIcon, Trash2Icon } from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { cn } from "@/lib/utils";
import { $isMathNode } from "../../core/nodes/math/node";

interface MathComponentProps {
  equation: string;
  inline: boolean;
  nodeKey: NodeKey;
}

const escapeHtml = (value: string) => {
  return value
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#039;");
};

export function MathComponent({
  equation,
  inline,
  nodeKey,
}: MathComponentProps) {
  const [editor] = useLexicalComposerContext();
  const editable = useLexicalEditable();
  const [isSelected, setSelected, clearSelection] =
    useLexicalNodeSelection(nodeKey);
  const [isEditing, setIsEditing] = useState(false);
  const [draftEquation, setDraftEquation] = useState(equation);
  const [draftInline, setDraftInline] = useState(inline);
  const mathRef = useRef<HTMLSpanElement | HTMLDivElement | null>(null);
  const textareaRef = useRef<HTMLTextAreaElement | null>(null);

  const openEditor = () => {
    setDraftEquation(equation);
    setDraftInline(inline);
    setIsEditing(true);
  };

  useEffect(() => {
    if (isEditing) {
      const timer = setTimeout(() => {
        textareaRef.current?.focus({ preventScroll: true });
      }, 0);
      return () => clearTimeout(timer);
    }
  }, [isEditing]);

  const html = useMemo(() => {
    try {
      return katex.renderToString(equation || "\\text{math}", {
        displayMode: !inline,
        errorColor: "#cc0000",
        throwOnError: false,
      });
    } catch (_err) {
      return `<span class="text-destructive">${escapeHtml(equation || "math")}</span>`;
    }
  }, [equation, inline]);

  const previewHtml = useMemo(() => {
    try {
      return katex.renderToString(draftEquation || "\\text{math}", {
        displayMode: !draftInline,
        errorColor: "#cc0000",
        throwOnError: false,
      });
    } catch (_err) {
      return `<span class="text-destructive">${escapeHtml(draftEquation || "math")}</span>`;
    }
  }, [draftEquation, draftInline]);

  useEffect(() => {
    if (!editable) {
      return;
    }

    const removeNode = (event: KeyboardEvent) => {
      const selection = $getSelection();
      if (!(isSelected && $isNodeSelection(selection))) {
        return false;
      }

      event.preventDefault();
      editor.update(() => {
        const node = $getNodeByKey(nodeKey);
        if ($isMathNode(node)) {
          node.remove();
        }
      });
      return true;
    };

    return mergeRegister(
      editor.registerCommand(
        CLICK_COMMAND,
        (event) => {
          if (mathRef.current?.contains(event.target as Node)) {
            if (event.shiftKey) {
              setSelected(!isSelected);
            } else {
              clearSelection();
              setSelected(true);
            }
            return true;
          }
          return false;
        },
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        KEY_BACKSPACE_COMMAND,
        removeNode,
        COMMAND_PRIORITY_LOW
      ),
      editor.registerCommand(
        KEY_DELETE_COMMAND,
        removeNode,
        COMMAND_PRIORITY_LOW
      )
    );
  }, [clearSelection, editable, editor, isSelected, nodeKey, setSelected]);

  const handleSave = () => {
    editor.update(() => {
      const node = $getNodeByKey(nodeKey);
      if ($isMathNode(node)) {
        node.setEquation(draftEquation);
        node.setInline(draftInline);
      }
    });
    setIsEditing(false);

    // Re-select the edited math node so that, when the popover closes and the
    // ContentEditable regains focus, the browser keeps scroll anchored on the
    // node the user was editing instead of jumping back to the collapsed caret
    // elsewhere in the document.
    clearSelection();
    setSelected(true);
    requestAnimationFrame(() => {
      editor.getRootElement()?.focus({ preventScroll: true });
    });
  };

  const handleDelete = () => {
    editor.update(() => {
      const node = $getNodeByKey(nodeKey);
      if ($isMathNode(node)) {
        node.remove();
      }
    });
    setIsEditing(false);
  };

  return (
    <span
      className={cn(
        "relative inline-block align-middle",
        !inline && "my-2 block text-center"
      )}
      ref={mathRef}
    >
      <Popover
        onOpenChange={(open) => {
          if (editable) {
            if (open) {
              openEditor();
            } else {
              setIsEditing(false);
            }
          }
        }}
        open={isEditing && editable}
      >
        <PopoverTrigger
          render={
            // biome-ignore lint/a11y/useSemanticElements: span is used as container for inline rendered equation button
            <span
              aria-label="Math formula"
              className={cn(
                "rounded px-1.5 py-0.5 transition-all duration-150",
                isSelected && editable && "bg-muted/30 ring-2 ring-primary/40",
                editable && "cursor-pointer hover:bg-muted/40"
              )}
              // biome-ignore lint/security/noDangerouslySetInnerHtml: KaTeX output HTML is sanitized equation output
              dangerouslySetInnerHTML={{ __html: html }}
              onClick={() => {
                if (editable) {
                  openEditor();
                }
              }}
              onKeyDown={(e) => {
                if (editable && (e.key === "Enter" || e.key === " ")) {
                  e.preventDefault();
                  openEditor();
                }
              }}
              role="button"
              tabIndex={editable ? 0 : -1}
            />
          }
        />

        {editable ? (
          <PopoverContent
            align="center"
            className="w-72 p-3"
            finalFocus={false}
            initialFocus={false}
            side="bottom"
            sideOffset={4}
          >
            <div className="flex flex-col gap-2.5">
              <div className="flex items-center justify-between font-medium text-muted-foreground text-xs">
                <span>Edit TeX Equation</span>
                <div className="flex items-center gap-1 rounded-md bg-muted/50 p-0.5">
                  <button
                    className={cn(
                      "rounded px-2 py-0.5 font-medium text-[11px] transition-colors",
                      draftInline
                        ? "bg-background text-foreground shadow-xs"
                        : "text-muted-foreground hover:text-foreground"
                    )}
                    onClick={() => setDraftInline(true)}
                    type="button"
                  >
                    Inline
                  </button>
                  <button
                    className={cn(
                      "rounded px-2 py-0.5 font-medium text-[11px] transition-colors",
                      draftInline
                        ? "text-muted-foreground hover:text-foreground"
                        : "bg-background text-foreground shadow-xs"
                    )}
                    onClick={() => setDraftInline(false)}
                    type="button"
                  >
                    Block
                  </button>
                </div>
              </div>

              <textarea
                aria-label="TeX equation"
                className="w-full rounded-md border border-input bg-background px-3 py-1.5 font-mono text-xs ring-offset-background placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
                onChange={(e) => setDraftEquation(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter" && (e.metaKey || e.ctrlKey)) {
                    e.preventDefault();
                    handleSave();
                  } else if (e.key === "Escape") {
                    e.preventDefault();
                    setIsEditing(false);
                  }
                }}
                placeholder="e.g. f(x) = x^2"
                ref={textareaRef}
                rows={2}
                value={draftEquation}
              />

              <div className="flex min-h-9 items-center justify-center overflow-x-auto rounded-md border border-border/40 bg-muted/20 p-2">
                {/* biome-ignore lint/security/noDangerouslySetInnerHtml: KaTeX output HTML is sanitized equation preview */}
                <span dangerouslySetInnerHTML={{ __html: previewHtml }} />
              </div>

              <div className="flex items-center justify-between pt-1">
                <button
                  className="inline-flex items-center gap-1 rounded px-2 py-1 font-medium text-destructive text-xs transition-colors hover:bg-destructive/10 hover:text-destructive/80"
                  onClick={handleDelete}
                  type="button"
                >
                  <Trash2Icon className="size-3.5" />
                  Remove
                </button>

                <div className="flex items-center gap-1.5">
                  <button
                    className="rounded px-2.5 py-1 font-medium text-muted-foreground text-xs transition-colors hover:bg-muted hover:text-foreground"
                    onClick={() => setIsEditing(false)}
                    type="button"
                  >
                    Cancel
                  </button>
                  <button
                    className="inline-flex items-center gap-1 rounded bg-primary px-2.5 py-1 font-medium text-primary-foreground text-xs shadow-xs transition-colors hover:bg-primary/90"
                    onClick={handleSave}
                    type="button"
                  >
                    <CheckIcon className="size-3.5" />
                    Save
                  </button>
                </div>
              </div>
            </div>
          </PopoverContent>
        ) : null}
      </Popover>
    </span>
  );
}

import { $createParagraphNode, type ElementNode } from "lexical";
import { CalculatorIcon } from "lucide-react";
import { $createMathNode, MathNode } from "../../core/nodes/math/node";
import {
  MATH_BLOCK_MARKDOWN_TRANSFORMER,
  MATH_INLINE_MARKDOWN_TRANSFORMER,
} from "../../core/nodes/math/transformers";
import type { ExtraEditorFeature } from "../../core/types";
import { replaceCurrentBlock } from "../slash-command/utils";
import { MathPlugin } from "./plugin";

const applyMathCommand = (targetElement: ElementNode): void => {
  const mathNode = $createMathNode({
    equation: "f(x) = c",
    inline: false,
  });
  const paragraph = $createParagraphNode();

  targetElement.replace(mathNode);
  mathNode.insertAfter(paragraph);
  paragraph.select();
};

/**
 * Installs the math feature: the `MathNode`, KaTeX rendering, the `$...$` /
 * `$$...$$` markdown transformers and the shared insert-menu entry. Ships as
 * the `editor-math` registry item and pulls `katex`.
 */
export const mathFeature: ExtraEditorFeature = {
  id: "math",
  nodes: [MathNode],
  plugin: MathPlugin,
  slashCommands: [
    {
      command: {
        description: "Insert TeX math equation",
        icon: CalculatorIcon,
        id: "math",
        keywords: ["math", "latex", "katex", "equation", "formula", "tex"],
        label: "Math Block",
      },
      run: (editor) => {
        replaceCurrentBlock(editor, applyMathCommand);
      },
    },
  ],
  transformers: [
    MATH_INLINE_MARKDOWN_TRANSFORMER,
    MATH_BLOCK_MARKDOWN_TRANSFORMER,
  ],
};

"use client";

import { useLexicalComposerContext } from "@lexical/react/LexicalComposerContext";
import { $insertNodeToNearestRoot, mergeRegister } from "@lexical/utils";
import {
  $getSelection,
  $insertNodes,
  $isRangeSelection,
  COMMAND_PRIORITY_EDITOR,
} from "lexical";
import { useEffect } from "react";
import { $createMathNode, type MathPayload } from "../../core/nodes/math/node";
import { INSERT_MATH_COMMAND } from "./commands";

export function MathPlugin(): null {
  const [editor] = useLexicalComposerContext();

  useEffect(() => {
    return mergeRegister(
      editor.registerCommand<MathPayload>(
        INSERT_MATH_COMMAND,
        (payload) => {
          const { equation, inline = true } = payload;
          const mathNode = $createMathNode({ equation, inline });

          const selection = $getSelection();
          if ($isRangeSelection(selection)) {
            if (inline) {
              $insertNodes([mathNode]);
            } else {
              $insertNodeToNearestRoot(mathNode);
            }
          } else {
            $insertNodes([mathNode]);
          }

          return true;
        },
        COMMAND_PRIORITY_EDITOR
      )
    );
  }, [editor]);

  return null;
}
